        Scanner sc = new Scanner(System.in);
        ArrayList<String> courses = new ArrayList<>();
        String ligne = sc.nextLine();
        while (!ligne.equals("fin")) {
            courses.add(ligne.trim());
            ligne = sc.nextLine();
        }
        courses.remove(0);
        System.out.println(courses.size() + " articles");
