import java.util.ArrayList;
import java.util.Scanner;

public class Main {
    static int noteDe(String ligne) {
        return Integer.parseInt(ligne.split(",")[1].trim());
    }

    static String nomDe(String ligne) {
        return ligne.split(",")[0].trim();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        ArrayList<String> admis = new ArrayList<>();
        int total = 0;
        String ligne = sc.nextLine();
        while (!ligne.equals("fin")) {
            total++;
            if (noteDe(ligne) >= 10) {
                admis.add(nomDe(ligne));
            }
            ligne = sc.nextLine();
        }
        System.out.println("Admis : " + admis.size() + " sur " + total);
        for (String nom : admis) {
            System.out.println(nom);
        }
    }
}
